plugin.json:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "author": {
    "email": "leon.i.long.yu@gmail.com",
    "name": "Leon Yu"
  },
  "description": "Design, implement, test, and review role-based access control in new and existing software projects.",
  "extensions": {
    "com.openai": {
      "interface": {
        "category": "Productivity",
        "defaultPrompt": [
          "帮我使用 FastAPI 和 React 创建 RBAC 系统。",
          "检查我的项目中的权限漏洞，并实现修复和测试。",
          "为多租户应用设计角色、权限矩阵及安全的授权流程。"
        ],
        "developerName": "Leon Yu",
        "displayName": "RBAC Builder",
        "longDescription": "使用 FastAPI、SQLAlchemy、Alembic 和 React 构建可扩展权限基础，覆盖学员、顾客、员工、多租户与门店隔离，以及可选 Redis、前后端日次日志、数据库登录历史和用户操作审计。适用于英语学习、酒店和娱乐中心应用。 支持可扩展的中英文界面、独立主题配色与浅色/深色/跟随系统模式、用户偏好同步和响应式管理界面。",
        "shortDescription": "设计、实现和审查 RBAC 权限系统"
      }
    }
  },
  "name": "rbac-builder",
  "version": "0.3.1"
}
